package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.factorialDouble.
 * Uses JUnit 4 and Java 11.
 */
public class MathUtils_factorialDouble_TriageGen1Test {

    private static final double EPSILON = 1e-9;









    @Test
    public void testFactorialDouble_LargeN() {
        // Tests the branch: return Math.floor(Math.exp(factorialLog(n)) + 0.5);
        // This branch is taken when n >= 21
        // 21! is approximately 5.109094217170944e+19
        // We use a slightly larger value to ensure the log/exp path is exercised
        double result = MathUtils.factorialDouble(21);

        // Since we can't easily hardcode the exact double precision of 21! without 
        // knowing the internal MathUtils.factorialLog implementation, 
        // we verify it is a positive large number.
        // However, mathematically 21! = 51090942171709440000
        double expected = 5.109094217170944E19; 
        // We allow a relative error margin for large floating point numbers
        double relativeError = Math.abs(result - expected) / expected;
        assert(relativeError < 1e-12);
    }


}

